#!/usr/bin/env python3
"""Render a Claude Code session .jsonl transcript as readable plain text.

Extracts user prompts and assistant text replies (skipping thinking blocks,
tool_use/tool_result payloads, and system/meta events), with a short
one-line marker wherever a tool was called so the flow of the session is
still traceable without dumping raw tool I/O.
"""
import json
import sys


def text_from_content(content):
    if isinstance(content, str):
        return content
    parts = []
    if isinstance(content, list):
        for block in content:
            if not isinstance(block, dict):
                continue
            btype = block.get("type")
            if btype == "text":
                parts.append(block.get("text", ""))
            elif btype == "tool_use":
                name = block.get("name", "tool")
                parts.append(f"[called tool: {name}]")
            elif btype == "tool_result":
                # tool results are noisy; note only that one occurred
                continue
    return "\n".join(p for p in parts if p.strip())


def render(path, out_path):
    lines_out = []
    with open(path, "r", errors="replace") as f:
        for raw in f:
            raw = raw.strip()
            if not raw:
                continue
            try:
                ev = json.loads(raw)
            except json.JSONDecodeError:
                continue

            etype = ev.get("type")
            if etype not in ("user", "assistant"):
                continue

            message = ev.get("message", {})
            role = message.get("role", etype)
            content = message.get("content")
            text = text_from_content(content)
            if not text.strip():
                continue

            # skip pure tool_result-only user turns (no human text)
            if etype == "user" and isinstance(content, list):
                only_tool_results = all(
                    isinstance(b, dict) and b.get("type") == "tool_result"
                    for b in content
                )
                if only_tool_results:
                    continue

            label = "USER" if role == "user" else "ASSISTANT"
            lines_out.append(f"\n=== {label} ===\n{text.strip()}\n")

    with open(out_path, "w") as f:
        f.write("".join(lines_out))
    print(f"wrote {out_path} ({len(lines_out)} turns)")


if __name__ == "__main__":
    render(sys.argv[1], sys.argv[2])

